#include "GovernanceRuntime.hpp"
namespace elysium::fortress {bool GovernanceRuntime::upsertOffice(Office o,std::string&w){if(!o.id||!o.type){w="invalid office";return false;}offices_[o.id]=std::move(o);return true;}bool GovernanceRuntime::appoint(StableId id,StableId holder,std::string&w){auto i=offices_.find(id);if(i==offices_.end()){w="unknown office";return false;}i->second.holder=holder;return true;}bool GovernanceRuntime::addMandate(Mandate m,std::string&w){if(!m.id||!m.issuer||!m.scope){w="invalid mandate";return false;}return mandates_.emplace(m.id,std::move(m)).second;}bool GovernanceRuntime::resolveMandate(StableId id,MandateState s,std::string&w){auto i=mandates_.find(id);if(i==mandates_.end()){w="unknown mandate";return false;}if(i->second.state!=MandateState::Active){w="mandate inactive";return false;}i->second.state=s;return true;}std::optional<Office>GovernanceRuntime::office(StableId id)const{auto i=offices_.find(id);if(i==offices_.end())return std::nullopt;return i->second;}}
